const paths = computed(() => ICON_PATHS[props.name] || [])

const viewBox = '0 0 256 256'

const pxSize = computed(() => {
  // uni.upx2px 在各端把 750rpx 设计稿值换算为真实 px
  try {
    return uni.upx2px(props.size)
  } catch (e) {
    return props.size
  }
})

// 仅 MP-WEIXIN：不支持内联 svg，降级为 base64 image
const dataUri = computed(() => {
  const d = paths.value.join(' ')
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" fill="${props.color}"><path d="${d}"/></svg>`
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg)
})
